var _markdown = "\n\n# Basic Usage [#basic-usage]\n\n## Simple Example [#simple-example]\n\n```tsx\nimport React, { useState } from 'react';\nimport { View } from 'react-native';\nimport { TagInput, type ITags } from 'react-native-input-tag';\n\nexport default function App() {\n  const [tags, updateState] = useState<ITags>({ \n    tag: '', \n    tagsArray: [] \n  });\n\n  return (\n    <View style={{ flex: 1, padding: 20 }}>\n      <TagInput\n        label=\"Enter Tags\"\n        tags={tags}\n        updateState={updateState}\n        suggestions={['React', 'Native', 'JavaScript', 'TypeScript']}\n      />\n    </View>\n  );\n}\n```\n\n## With Custom Keys [#with-custom-keys]\n\n```tsx\n<TagInput\n  tags={tags}\n  updateState={updateState}\n  keysForTag=\",\" // Use comma to separate tags\n  suggestions={['React', 'Native', 'JavaScript']}\n/>\n```\n\n## With Autocomplete [#with-autocomplete]\n\n```tsx\n<TagInput\n  tags={tags}\n  updateState={updateState}\n  suggestions={[\n    'React Native',\n    'JavaScript',\n    'TypeScript',\n    'Node.js',\n    'MongoDB',\n    'PostgreSQL',\n  ]}\n  maxSuggestions={4}\n  highlightMatchedText={true}\n  caseSensitive={false}\n/>\n```\n\n## With Custom Styling [#with-custom-styling]\n\n```tsx\n<TagInput\n  tags={tags}\n  updateState={updateState}\n  containerStyle={{\n    backgroundColor: '#fff',\n    borderRadius: 8,\n    padding: 10,\n  }}\n  inputStyle={{\n    fontSize: 16,\n    color: '#333',\n  }}\n  tagStyle={{\n    backgroundColor: '#007bff',\n    borderRadius: 20,\n    paddingVertical: 5,\n    paddingHorizontal: 10,\n  }}\n  tagTextStyle={{\n    color: '#fff',\n    fontSize: 14,\n  }}\n/>\n```\n\n## With Validation [#with-validation]\n\n```tsx\n<TagInput\n  tags={tags}\n  updateState={(newTags) => {\n    // Custom validation\n    if (newTags.tagsArray.length <= 5) {\n      updateState(newTags);\n    }\n  }}\n  onValidation={(success) => {\n    console.log('Validation status:', success);\n  }}\n/>\n```\n\n## Try it Live [#try-it-live]\n\nSee these examples in action on our [Expo Snack](https://snack.expo.dev/@lekgwaraj/react-native-input-tag).\n";
